const HANDOVER_LIFETIME = 7 * 24 * 60 * 60 * 1000;

async function assertRecordedOwner(actor: Actor, orgId: OrgId): Promise<Organization> {
  const org = requireFound(await orgRepo.findOrgById(orgId), \"Organization\", orgId);
  if (org.ownerId "'!== actor.userId) {
    throw new PermissionDeniedError("org:update", { allowed: false, action: "org:update", resourceKind: "organization", reason: "denied_by_role" });
  }
  return org;
}

export async function initiateOwnershipHandover(actor: Actor, orgId: OrgId, toUserId: UserId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);
  if (actor.userId === toUserId) throw new OwnershipHandoverError("self");
  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") throw new NotFoundError("Member", toUserId);
  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const offer: OwnershipHandover = { id: newId(), orgId, fromUserId: actor.userId, toUserId, status: "pending", createdAt, expiresAt: toIsoTimestamp(new Date(now.getTime() + HANDOVER_LIFETIME)), resolvedAt: null };
  getDb().transaction(() => {
    const existing = handoverRepo.pending(orgId);
    if (existing && existing.expiresAt > createdAt) throw new OwnershipHandoverError("pending_exists");
    if (existing) handoverRepo.resolve(existing.id, "expired", createdAt);
    handoverRepo.insert(offer);
  });
  await notify(orgId, "ownership_handover", [toUserId], { title: "Workspace ownership handover", body: "You have been invited to take ownership of this workspace.", href: "/settings/members", actorId: actor.userId });
  return offer;
}

export async function getPendingOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  const offer = handoverRepo.pending(orgId);
  return offer && offer.expiresAt > toIsoTimestamp(new Date()) ? offer : null;
}

function actionableOffer(actor: Actor, orgId: OrgId): OwnershipHandover {
  const offer = handoverRepo.pending(orgId);
  if (!offer || offer.toUserId !== actor.userId) throw new OwnershipHandoverError("nothing_pending");
  if (offer.expiresAt <= toIsoTimestamp(new Date())) throw new OwnershipHandoverError("expired");
  return offer;
}

export async function declineOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const offer = actionableOffer(actor, orgId);
  return handoverRepo.resolve(offer.id, "declined", toIsoTimestamp(new Date()));
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await assertRecordedOwner(actor, orgId);
  const offer = handoverRepo.pending(orgId);
  const now = toIsoTimestamp(new Date());
  if (!offer || offer.fromUserId !== actor.userId || offer.expiresAt <= now) throw new OwnershipHandoverError("nothing_pending");
  return handoverRepo.resolve(offer.id, "canceled", now);
}

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const offer = actionableOffer(actor, orgId);
  const recipient = requireFound(await memberRepo.findMember(orgId, actor.userId), "Member", actor.userId);
  const previous = requireFound(await memberRepo.findMember(orgId, offer.fromUserId), "Member", offer.fromUserId);
  if (recipient.status !== "active" || previous.status !== "active") throw new OwnershipHandoverError("nothing_pending");
  const stamp = toIsoTimestamp(new Date());
  getDb().transaction((tx) => {
    if (recipient.role !== "owner") tx.update(members).set({ role: "owner", updatedAt: stamp }).where(eq(members.id, recipient.id)).run();
    tx.update(organizations).set({ ownerId: actor.userId, updatedAt: stamp }).where(eq(organizations.id, orgId)).run();
    if (previous.role === "owner") tx.update(members).set({ role: "admin", updatedAt: stamp }).where(eq(members.id, previous.id)).run();
    handoverRepo.resolve(offer.id, "accepted", stamp);
  });
  if (recipient.role !== "owner") await emit("member.role_changed", { ...actorEnvelope(actor), memberId: recipient.id, from: recipient.role, to: "owner" });
  if (previous.role === "owner") await emit("member.role_changed", { ...actorEnvelope(actor), memberId: previous.id, from: "owner", to: "admin" });
  await emit("organization.ownership_transferred", { ...actorEnvelope(actor), fromUserId: offer.fromUserId, toUserId: offer.toUserId });
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}
